// Writes the generated files under .generated/: the registry the Worker imports, the migration
// bundle, the registry types and the schema entries Drizzle Kit reads. None is committed.
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, relative } from 'node:path'
import { GENERATED, ROOT, KIT } from './paths.ts'
import { handlerKey, type Loaded, type Owner } from './load.ts'

function write(path: string, contents: string) {
  mkdirSync(join(path, '..'), { recursive: true })
  const previous = existsSync(path) ? readFileSync(path, 'utf8') : undefined
  if (previous !== contents) writeFileSync(path, contents)
}

const ident = (s: string) => s.replace(/[^a-zA-Z0-9]/g, '_')

/** The registry module: static imports of every manifest and handler, so the bundler sees them. */
export function registrySource(modules: Loaded[], from: string): string {
  const imports: string[] = []
  const entries: string[] = []
  const path = (file: string) => {
    const p = join(ROOT, file).replace(/\.ts$/, '')
    let r = relative(from, p).split('\\').join('/')
    if (!r.startsWith('.')) r = `./${r}`
    return r
  }
  modules.forEach((m, i) => {
    const name = `m${i}`
    imports.push(`import ${name} from '${path(m.found.manifestFile.slice(ROOT.length + 1))}'`)
    const groups: Record<string, string[]> = { listeners: [], jobs: [], tasks: [], facts: [], calls: [] }
    const contributions: Record<string, string[]> = {}
    for (const h of m.found.handlerFiles) {
      const local = `${name}_${h.kind}_${ident(h.point ?? '')}_${ident(h.name)}`
      imports.push(`import ${local} from '${path(h.file)}'`)
      if (h.kind === 'contributions') (contributions[h.point!] ??= []).push(`${JSON.stringify(h.name)}: ${local}`)
      else groups[h.kind]!.push(`${JSON.stringify(handlerKey(m.manifest.id, h))}: ${local}`)
    }
    const handlers = Object.entries(groups).map(([k, v]) => `${k}: { ${v.join(', ')} }`)
    handlers.push(`contributions: { ${Object.entries(contributions).map(([p, v]) => `${JSON.stringify(p)}: { ${v.join(', ')} }`).join(', ')} }`)
    entries.push(`  { manifest: ${name}, root: ${JSON.stringify(m.found.root)}, owner: ${JSON.stringify(m.found.owner)}, handlers: { ${handlers.join(', ')} } },`)
  })
  return `// Generated by scripts/generate.ts. Do not edit.
import { buildRegistry, type ModuleEntry } from '${relative(from, join(KIT, 'registry')).split('\\').join('/')}'
${imports.join('\n')}

export const entries: ModuleEntry[] = [
${entries.join('\n')}
]

export const registry = buildRegistry(entries)
`
}

export interface MigrationFile { owner: Owner, name: string, sql: string, checksum: string }

export const JOURNALS: Record<Owner, string> = { upstream: 'migrations', site: 'site/migrations', fixtures: 'tests/fixtures/migrations' }

export function readMigrations(owners: Owner[]): MigrationFile[] {
  const out: MigrationFile[] = []
  for (const owner of owners) {
    const dir = join(ROOT, JOURNALS[owner])
    if (!existsSync(dir)) continue
    for (const name of readdirSync(dir).sort()) {
      const file = join(dir, name, 'migration.sql')
      if (!existsSync(file)) continue
      const sql = readFileSync(file, 'utf8')
      out.push({ owner, name, sql, checksum: createHash('sha256').update(sql).digest('hex') })
    }
  }
  return out
}

function migrationsSource(migrations: MigrationFile[], version: string): string {
  return `// Generated by scripts/generate.ts. Do not edit.
import type { Migration } from '${relative(GENERATED, join(KIT, 'migrations')).split('\\').join('/')}'

export const release = ${JSON.stringify(version)}
export const migrations: Migration[] = ${JSON.stringify(migrations, null, 2)}
`
}

function typesSource(modules: Loaded[]): string {
  const imports = modules.map((m, i) => `import type m${i} from '${m.found.manifestFile.replace(/\.ts$/, '')}'`)
  const of = (helper: string) => modules.length ? modules.map((_, i) => `${helper}<typeof m${i}>`).join(' & ') : '{}'
  return `// Generated by scripts/generate.ts. Do not edit.
${imports.join('\n')}
import type { SettingsOf, AbilitiesOf, EventsOf, JobsOf } from '#kit/registry-types'

declare module '#kit/registry-types' {
  interface KitRegistry {
    settings: ${of('SettingsOf')}
    abilities: ${of('AbilitiesOf')}
    events: ${of('EventsOf')}
    jobs: ${of('JobsOf')}
  }
}
export {}
`
}

export function schemaSource(modules: Loaded[], owner: Owner): string {
  const lines = ['// Generated by scripts/generate.ts for Drizzle Kit. Do not edit.']
  modules.filter(m => m.found.owner === owner).forEach((m, i) => {
    lines.push(`import m${i} from '${m.found.manifestFile.replace(/\.ts$/, '')}'`)
    for (const [key, table] of Object.entries(m.manifest.tables ?? {})) {
      const name = (table as any)[Symbol.for('proscenium.table')].name
      lines.push(`export const ${name} = (m${i}.tables as any).${key}`)
    }
  })
  return `${lines.join('\n')}\n`
}

export function writeGenerated(modules: Loaded[], options: { version: string, registryFile?: string, migrationOwners?: Owner[] } = { version: '0.0.0' }) {
  const registryFile = options.registryFile ?? join(GENERATED, 'registry.ts')
  write(registryFile, `${registrySource(modules, join(registryFile, '..'))}export { migrations, release } from './${registryFile.endsWith('test-registry.ts') ? 'test-migrations' : 'migrations'}'\n`)
  const owners = options.migrationOwners ?? ['upstream', 'site']
  write(join(registryFile, '..', registryFile.endsWith('test-registry.ts') ? 'test-migrations.ts' : 'migrations.ts'), migrationsSource(readMigrations(owners), options.version))
  if (!registryFile.endsWith('test-registry.ts')) {
    write(join(GENERATED, 'types/registry.d.ts'), typesSource(modules))
  }
}
